def is_palindrome(text):
    s = text.replace(" ", "").casefold()
    return s == s[::-1]

def word_counts(text):
    out = {}
    for w in text.lower().split():
        out[w] = out.get(w, 0) + 1
    return out

def balanced(text):
    stack=[]
    pairs={")":"(","]":"[","}":"{"}
    for c in text:
        if c in "([{": stack.append(c)
        elif c in pairs:
            if not stack or stack.pop()!=pairs[c]: return False
    return not stack

def first_unique(text):
    counts={}
    for c in text: counts[c]=counts.get(c,0)+1
    return next((c for c in text if counts[c]==1),None)

def run_lengths(text):
    out=[]
    for c in text:
        if out and out[-1][0]==c: out[-1]=(c,out[-1][1]+1)
        else: out.append((c,1))
    return out

def missing_number(nums):
    n=len(nums)
    return n*(n+1)//2-sum(nums)

def two_sum(nums,target):
    seen={}
    for j,x in enumerate(nums):
        if target-x in seen: return (seen[target-x],j)
        seen[x]=j
    return None

def merge_intervals(intervals):
    out=[]
    for a,b in sorted(intervals):
        if out and a<=out[-1][1]: out[-1][1]=max(out[-1][1],b)
        else: out.append([a,b])
    return out

def nested_get(mapping,keys,fallback):
    value=mapping
    for key in keys:
        if not isinstance(value,dict) or key not in value: return fallback
        value=value[key]
    return value

def group_anagrams(words):
    groups={}
    for w in words: groups.setdefault("".join(sorted(w)),[]).append(w)
    return list(groups.values())

def invert_mapping(mapping):
    out={}
    for k,v in mapping.items(): out.setdefault(v,[]).append(k)
    return out

def prefix_sums(nums):
    out=[]
    total=0
    for x in nums: total+=x; out.append(total)
    return out

def primes_up_to(n):
    if n<2: return []
    flags=[True]*(n+1)
    flags[0]=flags[1]=False
    for p in range(2,int(n**0.5)+1):
        if flags[p]:
            for k in range(p*p,n+1,p): flags[k]=False
    return [p for p in range(n+1) if flags[p]]

def is_subsequence(s,text):
    i=0
    for c in text:
        if i<len(s) and c==s[i]: i+=1
    return i==len(s)

def common_prefix(words):
    if not words: return ""
    prefix=words[0]
    for w in words[1:]:
        while not w.startswith(prefix): prefix=prefix[:-1]
    return prefix

def second_largest(nums):
    values=sorted(set(nums))
    return values[-2] if len(values)>1 else None

def trim_zeros(nums):
    end=len(nums)
    while end and nums[end-1]==0: end-=1
    return nums[:end]

def list_difference(a,b):
    excluded=set(b)
    return [x for x in a if x not in excluded]

def unique_pairs(nums,target):
    seen=set()
    pairs=set()
    for x in nums:
        if target-x in seen: pairs.add(tuple(sorted((x,target-x))))
        seen.add(x)
    return sorted(pairs)

def min_coins(coins,amount):
    dp=[0]+[amount+1]*amount
    for value in range(1,amount+1):
        for coin in coins:
            if coin<=value: dp[value]=min(dp[value],dp[value-coin]+1)
    return dp[amount] if dp[amount]<=amount else -1

def shortest_distance(graph,start,goal):
    from collections import deque
    queue=deque([(start,0)])
    seen={start}
    while queue:
        node,distance=queue.popleft()
        if node==goal: return distance
        for neighbor in graph.get(node,[]):
            if neighbor not in seen:
                seen.add(neighbor); queue.append((neighbor,distance+1))
    return None
